const rows = $input.all().map(i => i.json);
if (!rows.length) return [];
const byBureau = {};
for (const r of rows) (byBureau[r.bureau] = byBureau[r.bureau] || []).push(r);
return Object.entries(byBureau).map(([bureau, items]) => ({ json: {
  case_id: items[0].case_id, bureau, round: items[0].round,
  consumer: { first_name: items[0].first_name, last_name: items[0].last_name,
    street: items[0].street, city: items[0].city, state: items[0].state,
    zip: items[0].zip, ssn_last4: items[0].ssn_last4 }, items } }));

const resp = $input.first().json;
const d = $('Build Letter Prompt').first().json;
const body = (resp.content && resp.content[0] && resp.content[0].text) || '';

// Banned phrases that violate CROA/FTC rules
const banned = [
  /guarantee/i, /guaranty/i,
  /erase your debt/i, /wipe.*credit/i,
  /new credit identity/i, /CPN/i, /shelf corporation/i,
  /will raise your score/i, /score.*guarantee/i,
  /100% removal/i, /permanent removal/i
];
const violations = banned.filter(rx => rx.test(body)).map(rx => 'Banned phrase matched: ' + rx.toString());

// Quality checks
const hasStatute   = /1681[a-z0-9()\/]*/i.test(body);
const hasDeadline  = /30.day|thirty.day/i.test(body);
const hasRemedy    = /delete|remove|correct|update/i.test(body);
const hasLength    = body.length > 300;

if (!hasStatute)  violations.push('Missing FCRA statute citation (§ 1681...)');
if (!hasDeadline) violations.push('Missing 30-day deadline reference');
if (!hasRemedy)   violations.push('Missing remedy request (delete/correct/remove)');
if (!hasLength)   violations.push('Letter body too short (< 300 chars)');

const passed = violations.length === 0;

return [{ json: {
  case_id: d.case_id,
  bureau: d.bureau,
  round: d.round,
  letter_body: body,
  item_ids: d.items.map(i => i.item_id),
  lint_passed: passed,
  lint_violations: violations,
  letter_status: passed ? 'pending_review' : 'needs_rewrite',
  requires_notarization: (d.round || 1) >= 3
} }];
